using namespace Assimp;

static constexpr aiImporterDesc desc = {
    "Assimp Binary Importer",
    "Gargaj / Conspiracy",
    "",
    "",
    aiImporterFlags_SupportBinaryFlavour | aiImporterFlags_SupportCompressedFlavour,
    0,
    0,
    0,
    0,
    "assbin"
};

// -----------------------------------------------------------------------------------
const aiImporterDesc *AssbinImporter::GetInfo() const {
    return &desc;
}

// -----------------------------------------------------------------------------------
bool AssbinImporter::CanRead(const std::string &pFile, IOSystem *pIOHandler, bool /*checkSig*/) const {
    IOStream *in = pIOHandler->Open(pFile);
    if (nullptr == in) {
        return false;
    }

    char s[32];
    const size_t read = in->Read(s, sizeof(char), 32);

    pIOHandler->Close(in);

    if (read < 19) {
      return false;
    }

    return strncmp(s, "ASSIMP.binary-dump.", 19) == 0;
}

// -----------------------------------------------------------------------------------
template <typename T>
T Read(IOStream *stream) {
    T t;
    size_t res = stream->Read(&t, sizeof(T), 1);
    if (res != 1) {
        throw DeadlyImportError("Unexpected EOF");
    }
    return t;
}

// -----------------------------------------------------------------------------------
template <>
aiVector3D Read<aiVector3D>(IOStream *stream) {
    aiVector3D v;
    v.x = Read<ai_real>(stream);
    v.y = Read<ai_real>(stream);
    v.z = Read<ai_real>(stream);
    return v;
}

// -----------------------------------------------------------------------------------
template <>
aiColor4D Read<aiColor4D>(IOStream *stream) {
    aiColor4D c;
    c.r = Read<ai_real>(stream);
    c.g = Read<ai_real>(stream);
    c.b = Read<ai_real>(stream);
    c.a = Read<ai_real>(stream);
    return c;
}

// -----------------------------------------------------------------------------------
template <>
aiQuaternion Read<aiQuaternion>(IOStream *stream) {
    aiQuaternion v;
    v.w = Read<ai_real>(stream);
    v.x = Read<ai_real>(stream);
    v.y = Read<ai_real>(stream);
    v.z = Read<ai_real>(stream);
    return v;
}

// -----------------------------------------------------------------------------------
template <>
aiString Read<aiString>(IOStream *stream) {
    aiString s;
    stream->Read(&s.length, 4, 1);
    if (s.length) {
        stream->Read(s.data, s.length, 1);
    }
    s.data[s.length] = 0;

    return s;
}

// -----------------------------------------------------------------------------------
template <>
aiVertexWeight Read<aiVertexWeight>(IOStream *stream) {
    aiVertexWeight w;
    w.mVertexId = Read<unsigned int>(stream);
    w.mWeight = Read<ai_real>(stream);
    return w;
}

// -----------------------------------------------------------------------------------
template <>
aiMatrix4x4 Read<aiMatrix4x4>(IOStream *stream) {
    aiMatrix4x4 m;
    for (unsigned int i = 0; i < 4; ++i) {
        for (unsigned int i2 = 0; i2 < 4; ++i2) {
            m[i][i2] = Read<ai_real>(stream);
        }
    }
    return m;
}

// -----------------------------------------------------------------------------------
template <>
aiVectorKey Read<aiVectorKey>(IOStream *stream) {
    aiVectorKey v;
    v.mTime = Read<double>(stream);
    v.mValue = Read<aiVector3D>(stream);
    return v;
}

// -----------------------------------------------------------------------------------
template <>
aiQuatKey Read<aiQuatKey>(IOStream *stream) {
    aiQuatKey v;
    v.mTime = Read<double>(stream);
    v.mValue = Read<aiQuaternion>(stream);
    return v;
}

// -----------------------------------------------------------------------------------
template <typename T>
void ReadArray(IOStream *stream, T *out, unsigned int size) {
    ai_assert(nullptr != stream);
    ai_assert(nullptr != out);

    for (unsigned int i = 0; i < size; i++) {
        out[i] = Read<T>(stream);
    }
}

// -----------------------------------------------------------------------------------
template <typename T>
void ReadBounds(IOStream *stream, T * /*p*/, unsigned int n) {
    // not sure what to do here, the data isn't really useful.
    stream->Seek(sizeof(T) * n, aiOrigin_CUR);
}

